const {THREE,RAPIER,sim,world,view,root}=game;
const rockets=[],effects=[];
const sphere=new THREE.SphereGeometry(1,12,8),box=new THREE.BoxGeometry(1,1,1),tube=new THREE.CylinderGeometry(.065,.065,.48,10),nose=new THREE.ConeGeometry(.105,.24,10);
const metal=new THREE.MeshStandardMaterial({color:0x56663a,metalness:.45,roughness:.5}),tip=new THREE.MeshStandardMaterial({color:0xb2a274}),flame=new THREE.MeshBasicMaterial({color:0xffbc35});
let loaded=true,reloading=0,kick=0,disposed=false;
const radius=1.25;
function vec(p){return new THREE.Vector3(p.x,p.y,p.z);}
function particle(p,type,velocity,size,life){
 if(effects.length>=220){const old=effects.shift();old.mesh.removeFromParent();old.mesh.material.dispose();}
 const mat=new THREE.MeshBasicMaterial({color:type==='fire'?0xffa128:type==='debris'?0x8c9587:0x727675,transparent:true,opacity:type==='smoke'?.5:1,depthWrite:false});
 const mesh=new THREE.Mesh(type==='debris'?box:sphere,mat);mesh.name='rpg-'+(type==='fire'?'explosion':type);mesh.position.copy(p);mesh.scale.setScalar(size);root.add(mesh);
 effects.push({mesh,type,velocity,size,life,total:life});return mesh;
}
function blast(p){
 particle(p,'fire',new THREE.Vector3(),.12,.55);
 for(let i=0;i<18;i++){
  const d=new THREE.Vector3(Math.random()-.5,Math.random()*.85,Math.random()-.5).normalize();
  particle(p,'debris',d.multiplyScalar(2+Math.random()*4),.055+Math.random()*.09,.8+Math.random()*.5);
 }
 for(let i=0;i<8;i++)particle(p.clone().add(new THREE.Vector3((Math.random()-.5)*.6,Math.random()*.5,(Math.random()-.5)*.6)),'smoke',new THREE.Vector3((Math.random()-.5)*.6,.8+Math.random(),(Math.random()-.5)*.6),.25,1.5);
 let destroyed=0;
 for(const e of game.entities){
  if(e.removed||['ground','near-bank','far-bank','rooftop'].includes(e.id))continue;
  const c=e.id==='guard'?{x:sim.guard.x,y:sim.guard.y+.9,z:sim.guard.z}:e.position;
  const dx=Math.max(0,Math.abs(p.x-c.x)-e.half.x),dy=Math.max(0,Math.abs(p.y-c.y)-e.half.y),dz=Math.max(0,Math.abs(p.z-c.z)-e.half.z);
  if(Math.hypot(dx,dy,dz)<=radius){game.removeEntity(e);destroyed++;}
 }
 const push=vec(sim.position).sub(p),dist=push.length();
 if(dist<radius+1.1){if(dist<.01)push.set(0,1,0);push.normalize().multiplyScalar(7*(1-dist/(radius+1.1)));push.y+=1;sim.player.applyImpulse(push,true);}
 game.sound(80,.28,.12,24);game.say(destroyed?'Impact! Cover destroyed. Press F to reload.':'Impact! Press F to reload.');
}
function guardHit(p,d,length){
 const guard=game.entities.find(e=>e.id==='guard'&&!e.removed);
 if(!guard||!sim.guardEnabled)return Infinity;
 const offset=p.clone().sub(new THREE.Vector3(sim.guard.x,sim.guard.y+.9,sim.guard.z));
 const b=offset.dot(d),c=offset.lengthSq()-.6*.6,disc=b*b-c;
 if(c<=0)return 0;if(disc<0)return Infinity;
 const t=-b-Math.sqrt(disc);return t>=0&&t<=length?t:Infinity;
}
function fire(){
 const d=vec(sim.aim);if(d.lengthSq()<.001)d.set(1,0,0);d.normalize();
 const p=vec(sim.position);p.y+=.86;
 const group=new THREE.Group();group.name='rpg-rocket';
 const body=new THREE.Mesh(tube,metal);body.rotation.z=-Math.PI/2;group.add(body);
 const head=new THREE.Mesh(nose,tip);head.rotation.z=-Math.PI/2;head.position.x=.32;group.add(head);
 for(let i=0;i<2;i++){const fin=new THREE.Mesh(box,metal);fin.scale.set(.18,.24,.025);fin.position.x=-.2;fin.rotation.x=i*Math.PI/2;group.add(fin);}
 const exhaust=new THREE.Mesh(nose,flame);exhaust.rotation.z=Math.PI/2;exhaust.position.x=-.36;exhaust.scale.set(.75,1.3,.75);group.add(exhaust);
 group.quaternion.setFromUnitVectors(new THREE.Vector3(1,0,0),d);group.position.copy(p).addScaledVector(d,.15);root.add(group);
 // Sweep from the eye on the first tick too: firing against a wall cannot skip it.
 rockets.push({mesh:group,p,d,age:0,smoke:0});
 loaded=false;kick=1;sim.player.applyImpulse(d.clone().multiplyScalar(-1.5),true);
 game.sound(170,.14,.1,48);game.say('Rocket away! Press F to reload.');
}
return {
 use(){
  if(disposed)return;
  if(reloading>0){game.say('Reloading…');return;}
  if(!loaded){reloading=1.2;game.sound(420,.09,.06,220);game.say('Loading a fresh rocket…');return;}
  fire();
 },
 step(dt){
  if(disposed)return;
  kick=Math.max(0,kick-dt*7);
  if(reloading>0){reloading=Math.max(0,reloading-dt);if(reloading===0){loaded=true;game.sound(650,.07,.06,850);game.say('Loaded. Aim and press F to fire.');}}
  for(let i=rockets.length-1;i>=0;i--){
   const r=rockets[i],length=22*dt;r.age+=dt;
   const hit=world.castRay(new RAPIER.Ray(r.p,r.d),length,true,undefined,undefined,undefined,sim.player);
   const wallDistance=hit?hit.timeOfImpact:Infinity;
   const distance=Math.min(wallDistance,guardHit(r.p,r.d,length));
   if(distance<=length){r.p.addScaledVector(r.d,distance);blast(r.p);r.mesh.removeFromParent();rockets.splice(i,1);continue;}
   r.p.addScaledVector(r.d,length);r.mesh.position.copy(r.p);r.smoke+=dt;
   if(r.smoke>=.03){r.smoke=0;particle(r.p.clone().addScaledVector(r.d,-.3),'smoke',new THREE.Vector3(0,.4,0),.09,.85);}
   if(r.age>=4){r.mesh.removeFromParent();rockets.splice(i,1);}
  }
  for(let i=effects.length-1;i>=0;i--){
   const e=effects[i];e.life-=dt;
   if(e.life<=0){e.mesh.removeFromParent();e.mesh.material.dispose();effects.splice(i,1);continue;}
   const age=1-e.life/e.total;
   if(e.type==='debris'){e.velocity.y-=9.81*dt;e.mesh.rotation.x+=dt*6;e.mesh.rotation.z+=dt*4;}
   e.mesh.position.addScaledVector(e.velocity,dt);
   if(e.type==='fire'){e.mesh.scale.setScalar(.12+radius*Math.min(1,age*3));e.mesh.material.color.setHSL(.12*(1-age),1,.55);}
   else if(e.type==='smoke')e.mesh.scale.setScalar(e.size+age*.55);
   e.mesh.material.opacity=(e.type==='smoke'?.5:1)*(1-age);
  }
 },
 render(){
  if(disposed)return;
  const d=vec(sim.aim).normalize(),right=new THREE.Vector3().crossVectors(d,new THREE.Vector3(0,1,0));
  if(right.lengthSq()<.001)right.set(0,0,1);right.normalize();
  const up=new THREE.Vector3().crossVectors(right,d).normalize();
  view.invention.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(d,up,right));
  const dip=reloading>0?Math.sin(Math.PI*(1-reloading/1.2)):0;
  view.invention.position.copy(vec(sim.position)).add(new THREE.Vector3(0,.86,0)).addScaledVector(d,.12-kick*.13).addScaledVector(right,.34).addScaledVector(up,-.42-dip*.15);
  view.invention.rotateZ(kick*.07-dip*.45);
 },
 dispose(){
  disposed=true;
  for(const r of rockets)r.mesh.removeFromParent();rockets.length=0;
  for(const e of effects){e.mesh.removeFromParent();e.mesh.material.dispose();}effects.length=0;
  for(const g of [sphere,box,tube,nose])g.dispose();for(const m of [metal,tip,flame])m.dispose();
 }
};

