const {sim,THREE,root,world}=game;
const gate=game.entities.find(e=>e.id==='gate'),wall=game.entities.find(e=>e.id==='wall-right');
assert(gate&&wall,'Courtyard provides a gate and destructible wall.');
const gateCollider=gate.collider,wallCollider=wall.collider;
sim.player.setTranslation({x:-6,y:.85,z:0},true);sim.player.setLinvel({x:0,y:0,z:0},true);sim.manual={x:0,y:0,z:0};
advance(2);
function aimAt(p){const from=sim.position;const d=new THREE.Vector3(p.x-from.x,p.y-(from.y+.86),p.z-from.z).normalize();sim.aim={x:d.x,y:d.y,z:d.z};return d;}
const d=aimAt(gate.position);
behavior.use();
assert(root.children.filter(o=>o.name==='rpg-rocket').length===1,'Firing creates a visible flying rocket.');
assert(new THREE.Vector3().copy(sim.player.linvel()).dot(d)<-.7,'Firing applies physical backward recoil.');
assert(!gate.removed&&gateCollider.isValid(),'Firing does not instantly destroy the gate.');
const start=root.children.find(o=>o.name==='rpg-rocket').position.clone();
advance(2);
const rocket=root.children.find(o=>o.name==='rpg-rocket');
assert(rocket&&rocket.position.distanceTo(start)>.3,'Rocket travels along its flight path.');
assert(!gate.removed,'Gate remains solid during early travel.');
assert(root.children.some(o=>o.name==='rpg-smoke'),'Moving rocket emits a smoke trail.');
advance(32);
assert(gate.removed&&!gateCollider.isValid(),'Rocket impact removes the actual gate collider.');
assert(root.children.some(o=>o.name==='rpg-explosion'),'Collision creates a visible expanding explosion.');
assert(!wall.removed&&wallCollider.isValid(),'Gate blast does not destroy a wall beyond its blast radius.');
behavior.use();
assert(!root.children.some(o=>o.name==='rpg-rocket'),'An empty launcher starts reloading instead of firing.');
behavior.use();advance(20);
assert(!root.children.some(o=>o.name==='rpg-rocket'),'Repeated presses cannot bypass reload time.');
advance(60);
sim.player.setTranslation({x:-6,y:.85,z:wall.position.z},true);sim.player.setLinvel({x:0,y:0,z:0},true);
advance(2);aimAt({x:wall.position.x,y:2.9,z:wall.position.z});
behavior.use();
assert(root.children.some(o=>o.name==='rpg-rocket'),'Reloaded launcher fires a second rocket.');
advance(2);assert(!wall.removed,'Second shot also travels before impact.');
advance(43);
assert(wall.removed&&!wallCollider.isValid(),'Second rocket physically destroys the aimed-at wall.');
behavior.dispose();
assert(!root.children.some(o=>o.name.startsWith('rpg-')),'Disposal removes projectiles and transient effects.');
assert(gate.removed&&wall.removed,'Destroyed structures stay destroyed after unequipping.');
